import { Dialog } from '@angular/cdk/dialog';
import { AsyncPipe } from '@angular/common';
import {
    Component,
    computed,
    inject,
    input,
    OnChanges,
    signal,
    SimpleChanges,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
    type JsonValue,
    metadata,
    Metadata as MetadataV7,
} from '@placeos/ts-client';
import { orThrow } from '@placeos/ts-client/compat';
import { VERSION } from '../../env/version';
import { AsyncHandler } from '../common/async-handler.class';
import { describeError, readError } from '../common/errors';
import { escapeHtml, parseMetadataDetails } from '../common/general';
import { i18n } from '../common/locale.service';
import {
    notifyError,
    notifySuccess,
    notifyWarn,
} from '../common/notifications';
import { loadMetadataBlocks, newItem } from '../common/placeos';
import { HashMap, PlaceResource } from '../common/types';
import { currentUser } from '../common/user-state';
import { validateJSONString } from '../common/validation';
import { openConfirmModal } from '../overlays/confirm-modal.component';
import {
    MetadataDetailsModalComponent,
    MetadataDetailsModalData,
} from '../overlays/metadata-details-modal.component';
import { MetadataHistoryModalComponent } from '../overlays/metadata-history-modal.component';
import { FormFieldComponent } from './controls/form-field.component';
import { SpinnerComponent } from './controls/spinner.component';
import { TooltipDirective } from './controls/tooltip.directive';
import { SettingsFieldComponent } from './custom-fields/settings-field.component';
import { IconComponent } from './icon.component';
import { DateFromPipe } from './pipes/date-from.pipe';
import { UserPipe } from './pipes/user.pipe';
import { TranslatePipe } from './translate.pipe';

interface Metadata extends MetadataV7 {
    match?: boolean;
    /** The block is not saved yet */
    new?: boolean;
}

export interface MetadataFormModel {
    name: string;
    description: string;
    editors: string[];
    details: string;
    schema: string;
}

function replaceDescTag(inputString, newContent) {
    return inputString.replace(/^\[.*?\]/, `[${newContent}]`);
}

@Component({
    selector: 'metadata-display',
    template: `
        <div class="flex items-center justify-between space-x-2">
            <button btn (click)="newMetadata()">
                {{ 'COMMON.METADATA_NEW' | translate }}
            </button>
            <app-form-field class="no-subscript">
                <icon prefix class="relative -left-1 text-2xl">search</icon>
                <input
                    [(ngModel)]="search_text"
                    (ngModelChange)="filterMetadata()"
                    placeholder="Search metadata blocks..."
                />
            </app-form-field>
        </div>
        @if (loading_list()) {
            <div class="flex w-full items-center justify-center p-16">
                <app-spinner diameter="32" />
            </div>
        } @else if (metadata()?.length > 0) {
            <div class="mt-4 space-y-2">
                @for (item of metadata(); track item.name) {
                    <div
                        block
                        [id]="'md-block-' + item.name"
                        class="border-base-300 rounded-sm border"
                        [class.shadow]="show_view() === item.name"
                        [class.opacity-30]="item.match === false"
                    >
                        <button
                            header
                            class="bg-base-200 flex w-full items-center space-x-2 px-2 py-1"
                            (click)="toggleView(item)"
                        >
                            <div class="min-w-0 px-2 text-left">
                                <h3 class="truncate font-mono text-sm">
                                    {{ names()[item.name] }}
                                </h3>
                                @if (descriptions()[item.name]) {
                                    <p
                                        class="text-base-content/60 truncate text-[0.625rem]"
                                    >
                                        {{ descriptions()[item.name] }}
                                    </p>
                                }
                            </div>
                            <div class="flex-1"></div>
                            <!-- A new block has no update time until it is saved -->
                            @if (item.updated_at) {
                                <div
                                    class="border-base-300 rounded-sm border px-2 py-1 font-mono text-[0.625rem] whitespace-nowrap"
                                    [appTooltip]="
                                        (item.modified_by_id | user | async)
                                            ?.name
                                    "
                                    appTooltipPosition="left"
                                >
                                    {{ item.updated_at * 1000 | dateFrom }}
                                </div>
                            }
                            <button
                                class="border-base-300 bg-base-100 flex items-center rounded-full border"
                                (click)="$event.stopPropagation()"
                            >
                                <button
                                    icon
                                    ripple
                                    (click)="saveMetadata(item)"
                                    [disabled]="
                                        !edited()[item.name] ||
                                        loading()[item.name]
                                    "
                                    [appTooltip]="'COMMON.SAVE' | translate"
                                >
                                    <icon class="text-xl">save</icon>
                                </button>
                                <button
                                    icon
                                    ripple
                                    (click)="editMetadataDetails(item)"
                                    [appTooltip]="
                                        'COMMON.METADATA_EDIT' | translate
                                    "
                                >
                                    <icon class="text-xl">edit</icon>
                                </button>
                                <button
                                    icon
                                    ripple
                                    (click)="viewMetadataHistory(item)"
                                    [appTooltip]="
                                        'COMMON.METADATA_HISTORY' | translate
                                    "
                                >
                                    <icon class="text-xl">history</icon>
                                </button>
                                <button
                                    icon
                                    ripple
                                    class="text-error"
                                    (click)="deleteMetadata(item.name)"
                                    [appTooltip]="
                                        'COMMON.METADATA_REMOVE' | translate
                                    "
                                >
                                    <icon class="text-xl">delete</icon>
                                </button>
                            </button>
                            <button icon ripple>
                                <icon class="text-2xl">{{
                                    show_view() === item.name
                                        ? 'keyboard_arrow_down'
                                        : 'chevron_right'
                                }}</icon>
                            </button>
                        </button>
                        <div
                            body
                            class="expandable"
                            [class.expanded]="show_view() === item.name"
                        >
                            <div>
                                <div class="border-base-300 h-130 border-t p-1">
                                    @if (show_view() === item.name) {
                                        <settings-form-field
                                            [ngModel]="
                                                form_map()[item.name]?.details
                                            "
                                            (ngModelChange)="
                                                updateMetadataField(
                                                    item.name,
                                                    'details',
                                                    $event
                                                )
                                            "
                                            [ngModelOptions]="{
                                                standalone: true,
                                            }"
                                            lang="json"
                                            [readonly]="false"
                                        />
                                    }
                                </div>
                            </div>
                        </div>
                    </div>
                }
            </div>
        } @else {
            <div
                class="flex w-full flex-col items-center justify-center space-y-8 p-16 opacity-30"
            >
                <icon class="text-8xl">settings_alert</icon>
                <div>{{ 'COMMON.METADATA_EMPTY' | translate }}</div>
            </div>
        }
    `,
    styles: [
        `
            [block] {
                transition: opacity 0.2s ease-in-out;
            }
        `,
    ],
    imports: [
        SpinnerComponent,
        TooltipDirective,
        FormFieldComponent,
        TranslatePipe,
        IconComponent,
        SettingsFieldComponent,
        FormsModule,
        DateFromPipe,
        UserPipe,
        AsyncPipe,
    ],
})
export class MetadataDisplayComponent
    extends AsyncHandler
    implements OnChanges
{
    private _dialog = inject(Dialog);
    public readonly item = input<PlaceResource>();
    /** List of metadata associated with the zone */
    public readonly metadata = signal<Metadata[]>([]);
    /** Map of form field groups to metadata fields */
    public readonly form_map = signal<HashMap<MetadataFormModel>>({});
    /** Map of metadata fields to whether they have been edited */
    public readonly edited = signal<HashMap<boolean>>({});
    /** Map of metadata properties to whether they are saving */
    public readonly loading = signal<HashMap<boolean>>({});
    /** Whether the metadata list is loading */
    public readonly loading_list = signal(false);
    /** Metadata contents to view */
    public readonly show_view = signal('');
    /** Search text for filtering metadata */
    public readonly search_text = signal('');
    public readonly change = signal(0);
    /**
     * Names that a save writes now. A rename shows in the list only after
     * its old block is removed, so a second save to the same name must wait
     */
    private readonly _saving_names = new Set<string>();
    public readonly names = computed(() => {
        this.change();
        const name_map = {};
        for (const key in this.form_map()) {
            name_map[key] = this.form_map()[key].name;
        }
        return name_map;
    });
    public readonly descriptions = computed(() => {
        this.change();
        const desc_map = {};
        for (const key in this.form_map()) {
            const desc = this.form_map()[key].description || '';
            desc_map[key] = desc; //.replace(/^\[.*?\]\s*/, '');
        }
        return desc_map;
    });

    public ngOnChanges(changes: SimpleChanges): void {
        if (changes.item && this.item()) {
            this.loadMetadata();
        }
    }

    public toggleView(item: Metadata) {
        this.show_view.update((current) =>
            current === item.name ? '' : (item.name as string),
        );
        this.search_text.set('');
        this.filterMetadata();
    }

    public newMetadata() {
        this.metadata.update((l) => {
            l.push({
                ...newItem(MetadataV7, {
                    name: `new_field_${Math.floor(Math.random() * 999_999_999)}`,
                    details: {},
                }),
                new: true,
            });
            return l;
        });
        this.generateForms();
    }

    public editMetadataDetails(field: MetadataV7) {
        const form = this.form_map()[field.name];
        this._dialog.open<
            unknown,
            MetadataDetailsModalData,
            MetadataDetailsModalComponent
        >(MetadataDetailsModalComponent, {
            maxWidth: '95vw',
            data: {
                value: form,
                existing_names: this.metadata()
                    .filter((i) => i.name !== field.name)
                    .map((i) => i.name),
                update: (value: MetadataFormModel) =>
                    this.updateMetadataDetails(field.name, value),
            },
        });
    }

    /**
     * Delete the given metadata field
     * @param field Name of the field to remove
     */
    public async deleteMetadata(field: string) {
        const result = await openConfirmModal(
            {
                title: `Remove Metadata block`,
                content: `
                <p>Are you sure you want delete the metadata property "${escapeHtml(field)}"?</p>
            `,
                icon: { type: 'icon', content: 'delete' },
            },
            this._dialog,
        );
        if (result.reason !== 'done') return;
        const is_new = !!this.metadata().find((prop) => prop?.name === field)
            ?.new;
        try {
            // Blocks that were never saved only exist locally
            if (!is_new)
                await metadata
                    .destroy({ id: this.item().id, name: field })
                    .then(orThrow);
        } catch (err) {
            return notifyError(
                `Error removing old "${field}" metadata. Error: ${await readError(
                    err,
                )}`,
            );
        } finally {
            result.close();
        }
        notifySuccess(`Successfully removed "${field}" metadata.`);
        this.metadata.set(
            this.metadata().filter((prop) => prop && prop.name !== field),
        );
        this.generateForms();
    }

    public filterMetadata() {
        const search = this.search_text().toLowerCase();
        if (search) this.show_view.set('');
        this.metadata.update((list) => {
            for (const block of list) {
                block.match =
                    block.name.toLowerCase().includes(search) ||
                    `${this.form_map()[block.name].name}`
                        .toLowerCase()
                        .includes(search);
            }
            return list;
        });
    }

    public saveMetadata(field: Metadata) {
        const form = this.form_map()[field.name];
        if (
            !form.name ||
            this.metadata()
                .filter((i) => i.name !== field.name)
                .some((item) => item.name === form.name) ||
            this._saving_names.has(form.name) ||
            validateJSONString({ value: form.details } as never)
        ) {
            return notifyError(`JSON for property "${form.name}" is invalid`);
        }
        const value = form;
        // Parse before the loading state, so empty or invalid JSON cannot
        // leave the save button disabled
        let data: JsonValue;
        try {
            data = JSON.parse(value.details);
        } catch {
            return notifyError(`JSON for property "${form.name}" is invalid`);
        }
        this.loading.update((m) => ({ ...m, [field.name]: true }));
        const desc = value.description;
        const new_desc = replaceDescTag(desc, `${VERSION.hash}|B`);
        if (
            /^\[.*?\]/.test(desc) &&
            data &&
            typeof data === 'object' &&
            !Array.isArray(data)
        ) {
            const user = currentUser();
            data = {
                ...data,
                edited_by: {
                    id: user.id,
                    name: user.name,
                    email: user.email,
                    auth_id: user.authority_id,
                    role: user.sys_admin
                        ? 'Admin'
                        : user.support
                          ? 'Support'
                          : 'User',
                },
            };
        }
        this._saving_names.add(value.name);
        return metadata
            .update({
                id: this.item().id,
                body: {
                    name: value.name,
                    description: new_desc,
                    editors: value.editors,
                    details: data,
                    // `null` keeps the schema of the block
                    schema_id: value.schema || null,
                },
            })
            .then(orThrow)
            .then(async (item: MetadataV7) => {
                // A rename saves a new block. Remove the old block after it.
                // A block that was never saved has no old block.
                const remove_error =
                    field.name !== value.name && !field.new
                        ? await metadata
                              .destroy({ id: this.item().id, name: field.name })
                              .then(orThrow)
                              .then(
                                  () => null,
                                  (err) => describeError(err),
                              )
                        : null;
                this.loading.update((m) => ({ ...m, [field.name]: false }));
                const index = this.metadata().findIndex(
                    (i) => i.name === field.name,
                );
                this.edited.update((m) => ({ ...m, [field.name]: false }));
                if (index >= 0) {
                    this.metadata.update((l) => {
                        // Both blocks are on the server, so show both
                        l.splice(index, remove_error === null ? 1 : 0, {
                            ...item,
                            new: false,
                        });
                        return l;
                    });
                }
                if (remove_error === null) {
                    notifySuccess(`Saved "${value.name}" metadata.`);
                } else {
                    notifyWarn(
                        i18n('COMMON.METADATA_RENAME_PARTIAL', {
                            name: value.name,
                            old_name: field.name,
                            error: remove_error,
                        }),
                    );
                }
                this.generateForms();
            })
            .catch((err) => {
                this.loading.update((m) => ({ ...m, [field.name]: false }));
                notifyError(
                    `Error saving "${
                        value.name
                    }" metadata. Error: ${describeError(err)}`,
                );
            })
            .finally(() => this._saving_names.delete(value.name));
    }

    /** Build a form for each block. Unsaved edits are kept unless `reset` is set */
    private generateForms(reset = false) {
        const forms = this.form_map();
        const edited = reset ? {} : this.edited();
        this.form_map.set({});
        this.edited.set({});
        this.metadata().forEach((group) => {
            if (edited[group.name] && forms[group.name]) {
                this.form_map.update((m) => {
                    m[group.name] = forms[group.name];
                    return m;
                });
                this.edited.update((m) => ({ ...m, [group.name]: true }));
                return;
            }
            const details = parseMetadataDetails(group.details);
            this.form_map.update((m) => {
                m[group.name] = {
                    name: group.name,
                    description: group.description,
                    editors: [...(group.editors || [])],
                    details: JSON.stringify(details, undefined, 4),
                    schema: group.schema_id,
                };
                return m;
            });
        });
    }

    public updateMetadataField(
        block: string,
        field: keyof MetadataFormModel,
        value: string | string[],
    ) {
        this.form_map.update((map) => ({
            ...map,
            [block]: {
                ...map[block],
                [field]: value,
            },
        }));
        this.edited.update((m) => ({ ...m, [block]: true }));
        this.change.set(Date.now());
    }

    private updateMetadataDetails(block: string, value: MetadataFormModel) {
        this.form_map.update((map) => ({
            ...map,
            [block]: value,
        }));
        this.edited.update((m) => ({ ...m, [block]: true }));
        this.change.set(Date.now());
    }

    private async loadMetadata() {
        this.loading_list.set(true);
        // The tab count of the item can have loaded the blocks already
        await loadMetadataBlocks(this.item().id)
            .then((blocks) => {
                this.metadata.set(blocks);
                this.generateForms(true);
            })
            .catch((err) =>
                notifyError(
                    `Error loading metadata. Error: ${describeError(err)}`,
                ),
            )
            .finally(() => this.loading_list.set(false));
    }

    public viewMetadataHistory(item: MetadataV7) {
        const item_value = this.item();
        this._dialog.open(MetadataHistoryModalComponent, {
            data: {
                id: this.item().id,
                parent_name: item_value['display_name'] || item_value.name,
                name: item.name,
            },
        });
    }
}
