import {
    Component,
    inject,
    OnInit,
    signal,
    WritableSignal,
} from '@angular/core';

import { DIALOG_DATA } from '@angular/cdk/dialog';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { metadata, type Metadata } from '@placeos/ts-client';
import { orThrow } from '@placeos/ts-client/compat';
import { describeError } from '../common/errors';
import { parseMetadataDetails } from '../common/general';
import { notifyError } from '../common/notifications';
import { DialogCloseDirective } from '../ui/controls/dialog';
import { FormFieldComponent } from '../ui/controls/form-field.component';
import { OptionComponent } from '../ui/controls/option.component';
import { SelectComponent } from '../ui/controls/select.component';
import { DialogTitleDirective } from '../ui/dialog-title.directive';
import { DiffViewerComponent } from '../ui/diff-viewer.component';
import { IconComponent } from '../ui/icon.component';
import { TranslatePipe } from '../ui/translate.pipe';

@Component({
    selector: 'metadata-history-modal',
    template: `
        <div
            class="bg-base-100 flex h-screen w-screen flex-col overflow-hidden"
        >
            <div
                class="bg-base-200 m-4 flex items-center justify-between rounded-sm px-4 py-2"
            >
                <h3 appDialogTitle class="text-xl font-medium">
                    {{ 'COMMON.METADATA_HISTORY' | translate }}
                </h3>
                <button
                    icon
                    ripple
                    appDialogClose
                    [attr.aria-label]="'COMMON.CLOSE' | translate"
                >
                    <icon>close</icon>
                </button>
            </div>
            <main class="flex flex-1 flex-col pb-4">
                <div class="mb-2 flex items-center space-x-2 px-4">
                    <div
                        class="border-base-300 relative h-14 min-w-48 rounded-sm border px-4 py-2"
                    >
                        <div
                            class="bg-base-100 absolute top-0 left-4 -translate-y-1/2 rounded-sm px-2 py-1 text-xs"
                        >
                            {{ 'COMMON.METADATA_OWNER' | translate }}
                        </div>
                        <div class="truncate">
                            {{ parent_name || id }}
                        </div>
                        @if (parent_name) {
                            <div class="text-xs opacity-30">
                                {{ id }}
                            </div>
                        }
                    </div>
                    <div
                        class="border-base-300 relative flex h-14 min-w-48 items-center rounded-sm border px-4 py-2"
                    >
                        <div
                            class="bg-base-100 absolute top-0 left-4 -translate-y-1/2 rounded-sm px-2 py-1 text-xs"
                        >
                            {{ 'COMMON.METADATA_KEY' | translate }}
                        </div>
                        <div class="truncate font-mono text-lg">
                            {{ name }}
                        </div>
                    </div>
                </div>
                <div
                    class="mb-2 flex items-center justify-between space-x-2 px-4"
                >
                    <app-form-field class="w-[20rem]">
                        <app-select
                            [(ngModel)]="first"
                            (selectionChange)="select(0, $event.value)"
                            (openedChange)="first_open.set($event)"
                            placeholder="Select metadata version"
                        >
                            @for (
                                item of history();
                                track item;
                                let i = $index
                            ) {
                                @if (
                                    first_open() ||
                                    i < CLOSED_OPTIONS ||
                                    item === first
                                ) {
                                    <app-option
                                        [value]="item"
                                        class="leading-tight"
                                    >
                                        <div class="">
                                            {{
                                                item.updated_at * 1000
                                                    | date: 'mediumDate'
                                            }},
                                            {{
                                                item.updated_at * 1000
                                                    | date: 'shortTime'
                                            }}
                                        </div>
                                        <div
                                            class="truncate text-xs opacity-30"
                                        >
                                            {{ item.description }}
                                        </div>
                                    </app-option>
                                }
                            }
                        </app-select>
                        @if (first) {
                            <div hint class="truncate">
                                {{ first.description }}
                            </div>
                        }
                    </app-form-field>
                    <app-form-field class="w-[20rem]">
                        <app-select
                            [(ngModel)]="second"
                            (selectionChange)="select(1, $event.value)"
                            (openedChange)="second_open.set($event)"
                            placeholder="Compare with"
                        >
                            @for (
                                item of history();
                                track item;
                                let i = $index
                            ) {
                                @if (
                                    item !== first &&
                                    (second_open() ||
                                        i < CLOSED_OPTIONS ||
                                        item === second())
                                ) {
                                    <app-option
                                        [value]="item"
                                        class="leading-tight"
                                    >
                                        <div class="">
                                            {{
                                                item.updated_at * 1000
                                                    | date: 'mediumDate'
                                            }},
                                            {{
                                                item.updated_at * 1000
                                                    | date: 'shortTime'
                                            }}
                                        </div>
                                        <div
                                            class="truncate text-xs opacity-30"
                                        >
                                            {{ item.description }}
                                        </div>
                                    </app-option>
                                }
                            }
                        </app-select>
                        @if (second()) {
                            <div hint class="truncate">
                                {{ second()?.description }}
                            </div>
                        }
                    </app-form-field>
                </div>
                <div class="relative w-full flex-1 px-4">
                    @if (first_details() || second_details()) {
                        <diff-viewer
                            [modified]="second_details() || ''"
                            [original]="first_details() || ''"
                        />
                    }
                    @if (!(first_details() && second_details())) {
                        <div
                            class="bg-base-200 flex h-full w-full items-center justify-center rounded-lg opacity-40"
                        >
                            Select 2 versions of the metadata to get started
                        </div>
                    }
                </div>
            </main>
        </div>
    `,
    styles: [``],
    imports: [
        DialogCloseDirective,
        OptionComponent,
        SelectComponent,
        FormFieldComponent,
        DialogTitleDirective,
        DiffViewerComponent,
        FormsModule,
        TranslatePipe,
        IconComponent,
        DatePipe,
    ],
})
export class MetadataHistoryModalComponent implements OnInit {
    private _data = inject<{
        id: string;
        parent_name: string;
        name: string;
    }>(DIALOG_DATA);

    public readonly id = this._data.id;
    public readonly parent_name = this._data.parent_name;
    public readonly name = this._data.name;

    public readonly history: WritableSignal<Metadata[]> = signal([]);

    public first = null;
    public readonly second = signal(null);
    // The history can hold thousands of versions. A closed select renders
    // only a few options and the selected one; a select does not open
    // without options.
    public readonly CLOSED_OPTIONS = 20;
    public readonly first_open = signal(false);
    public readonly second_open = signal(false);
    public readonly first_details = signal('');
    public readonly second_details = signal('');

    public async ngOnInit() {
        const history = await metadata
            .history({ id: this._data.id, name: this._data.name, limit: 5000 })
            .then(orThrow)
            // The API groups the versions by metadata name. 6.x gave them in one list, last first
            .then((by_name) => Object.values(by_name).flat().reverse())
            .catch((err) => {
                notifyError(
                    `Failed to load metadata history. Error: ${describeError(err)}`,
                );
                return [] as Metadata[];
            });
        this.history.set(history);
    }

    public select(idx: 0 | 1, item: Metadata) {
        if (idx === 0) {
            this.first_details.set(detailsText(item));
            if (this.first === this.second()) {
                this.second.set(null);
                this.second_details.set('');
            }
        } else {
            this.second_details.set(detailsText(item));
        }
    }
}

/** The details of a version as formatted JSON. JSON text from the API is parsed first */
function detailsText(item: Metadata) {
    return JSON.stringify(parseMetadataDetails(item.details), undefined, 4);
}
